import subprocess,json,pathlib,datetime,sys
name=sys.argv[1]
q="""SELECT json_build_object('utc',clock_timestamp(),'database_bytes',pg_database_size(current_database()),'counts',json_build_object('nodes',(SELECT count(*) FROM nodes),'edges',(SELECT count(*) FROM edges),'revisions',(SELECT count(*) FROM node_revisions),'history_entries',(SELECT count(*) FROM history_entries),'edge_versions',(SELECT count(*) FROM edge_versions),'link_sets',(SELECT count(*) FROM link_sets),'link_memberships',(SELECT count(*) FROM link_set_members),'changesets',(SELECT count(*) FROM change_sets)),'tables',(SELECT json_agg(s) FROM (SELECT relname,pg_relation_size(oid) heap_bytes,pg_indexes_size(oid) index_bytes,pg_total_relation_size(oid) total_bytes FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r' ORDER BY relname) s),'database_stats',(SELECT row_to_json(s) FROM pg_stat_database s WHERE datname=current_database()))"""
r=subprocess.check_output(['docker','exec','aq-graph-schema7-load-pg','psql','-U','postgres','-d','aq_graph_bench_schema7','-Atc',q],text=True)
pathlib.Path('docs/performance/schema7-load-optimized/'+name+'.json').write_text(json.dumps(json.loads(r),indent=2)+'\n')
